361	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
362	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed fiscal year since registration).
363	     */
364	    @Transient
365	    public Integer getMembershipPoints() {
366	        int points = 0;
367	        if (hasEmail()) {
368	            points += EMAIL_POINTS;
369	        }
370	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
371	            points += NO_NAMESAKE_POINTS;
372	        }
373	        if (hasLargeHousehold()) {
374	            points += LARGE_HOUSEHOLD_POINTS;
375	        }
376	        if (hasQualifyingTenure()) {
377	            points += TENURE_POINTS;
378	        }
379	        return points;
380	    }
381	
382	    /**
383	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
384	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
385	     */
386	    @Transient
387	    public Integer getMembershipLevel() {
388	        int points = getMembershipPoints();
389	        if (points <= 1) {
390	            return 1;
391	        }
392	        if (points <= 3) {
393	            return 2;
394	        }
395	        if (points <= 5) {
396	            return 3;
397	        }
398	        return 4;
399	    }
400	
401	    /**
402	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
403	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
404	     * qualify.
405	     */
406	    private boolean hasLargeHousehold() {
407	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
408	    }
409	
410	    /**
411	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS} elapsed
412	     * fiscal year, i.e. more than that many fiscal years have elapsed between the fiscal year of the
413	     * {@code registrationDate} and the fiscal year of today. Owners without a registration date have
414	     * no measurable tenure and do not qualify.
415	     */
416	    private boolean hasQualifyingTenure() {
417	        if (this.registrationDate == null) {
418	            return false;
419	        }
420	        long elapsedFiscalYears = FiscalYear.of(this.registrationDate).yearsUntil(FiscalYear.of(LocalDate.now()));
421	        return elapsedFiscalYears > MEMBERSHIP_TENURE_THRESHOLD_FISCAL_YEARS;
422	    }
423	
424	    /** Whether this owner has a usable email address (present and not blank). */
425	    private boolean hasEmail() {
426	        return this.email != null && !this.email.isBlank();
427	    }
428	
429	    /**
