445	            return null;
446	        }
447	        return AgeBand.asOf(this.birthDate, this.registrationDate);
448	    }
449	
450	    /**
451	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
452	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
453	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
454	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
455	     * region is resolved directly from the postcode and city.
456	     */
457	    @Transient
458	    public String getLocality() {
459	        if (this.customerCode == null) {
460	            return LocalityResolver.regionFor(this.postcode, this.city);
461	        }
462	        int separator = this.customerCode.indexOf('-');
463	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
464	    }
465	
466	    /**
467	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
468	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
469	     * known timezone.
470	     */
471	    @Transient
472	    public String getTimezone() {
473	        return LocalityResolver.timezoneFor(getLocality());
474	    }
