487	     * on: the normalized telephone, email and household id joined with {@code '|'} as
488	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
489	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
490	     * because the telephone is part of the key, members of one household (same {@code householdId})
491	     * with different telephones have distinct keys and are not duplicates.
492	     */
493	    @Transient
494	    public String getIdentityKey() {
495	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
496	    }
497	
